-- Category description and sibling order, for the dam-ui category editor (POST /categories/changes).
-- The schema is not generated by Hibernate (ddl-auto=none), so apply this to MariaDB by hand.
ALTER TABLE categories
    ADD COLUMN description VARCHAR(2000) NULL,
    ADD COLUMN sort_order INT NOT NULL DEFAULT 0;

-- Number existing siblings by name so their current (alphabetical) order is kept.
UPDATE categories c
    JOIN (SELECT id,
                 ROW_NUMBER() OVER (PARTITION BY catalog_id, parent_id ORDER BY name) - 1 AS rn
          FROM categories) ranked ON ranked.id = c.id
SET c.sort_order = ranked.rn;
